create table wallet (balance bigint not null, member_money_id bigint generated by default as identity, membership_id bigint not null unique, aggregate_identifier varchar(255) not null, primary key (member_money_id), constraint wallet_balance_not_negative check (balance >= 0));
create table wallet_change (amount bigint not null, membership_id bigint not null, requested_at timestamp(6) with time zone not null, change_type varchar(255) not null check ((change_type in ('INCREASE','DECREASE'))), request_id varchar(255) not null, status varchar(255) not null check ((status in ('PENDING','SUCCEEDED','FAILED'))), primary key (request_id));
insert into wallet_change (amount, membership_id, requested_at, change_type, request_id, status) values (1000, 1, now(), 'INCREASE', 'upgrade-1', 'SUCCEEDED');
